/** One-off (owner, 15 Nov 2026): put back the selling price / MRP that purchase invoices changed on 13 Nov (the prices on the jar labels). */
function restoreLabelPrices15Nov() {
  const want = {}; [["NV-ALM-AMC-LSE", 1750.0, 2200.0], ["NV-ALM-MLK-LSE", 1750.0, 2200.0], ["NV-APR-ABA-LSE", 1750.0, 2200.0], ["NV-CAS-CPR-LSE", 1750.0, 2200.0], ["NV-CAS-SRK-LSE", 1950.0, 2450.0], ["NV-MIX-CLD-LSE", 2000.0, 2500.0], ["NV-NUT-PAB-LSE", 4850.0, 6050.0], ["NV-NUT-TLR-LSE", 4550.0, 5700.0], ["NV-PST-JMB-LSE", 2700.0, 3400.0], ["NV-PST-SRC-LSE", 2400.0, 3000.0], ["NV-RSN-BMP-LSE", 1750.0, 2200.0], ["NV-RSN-NKK-LSE", 1750.0, 2200.0], ["NV-SED-CHS-LSE", 750.0, 950.0], ["NV-SED-PSK-LSE", 950.0, 1200.0], ["NV-SED-SSK-LSE", 550.0, 700.0]].forEach(x => want[x[0]] = { sell: x[1], mrp: x[2] });
  const lock = LockService.getScriptLock(); lock.waitLock(30000); const out = [];
  try {
    const psh = tab_('products'), prows = psh.getRange(2, 1, psh.getLastRow() - 1, H.products.length).getValues(), now = new Date(), hist = [];
    prows.forEach(r => { const w = want[s_(r[PC.sku])]; if (!w) return; const os = n_(r[PC.sell]), om = n_(r[PC.mrp]); if (os === w.sell && om === w.mrp) return;
      r[PC.sell] = w.sell; r[PC.mrp] = w.mrp; r[PC.margin] = margin_(n_(r[PC.cost]), w.sell); r[PC.updated] = now;
      hist.push([now, s_(r[PC.sku]), r[PC.name], n_(r[PC.cost]) || '', n_(r[PC.cost]) || '', os, w.sell, om, w.mrp, 'Restored to label price – invoice had changed it (owner 15 Nov)', 'Owner']);
      out.push(s_(r[PC.sku]) + ' ' + os + '/' + om + ' → ' + w.sell + '/' + w.mrp); });
    if (hist.length) { psh.getRange(2, 1, prows.length, H.products.length).setValues(prows); append_('prices', hist); PropertiesService.getScriptProperties().setProperty('PRODUCTS_VER', String(Date.now())); }
  } finally { lock.releaseLock(); }
  try { syncProductsToNightClosing(); } catch (e) { out.push('NC sync: ' + e.message); }
  Logger.log(out.length + ' restored\n' + out.join('\n')); return out;
}
